from pybricks.hubs import PrimeHub
from pybricks.parameters import Axis, Direction, Port
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import StopWatch

# Set up.
HUB = PrimeHub(top_side=Axis.Z, front_side=Axis.X)
DRIVE_LEFT = Motor(Port.C, Direction.COUNTERCLOCKWISE)
DRIVE_RIGHT = Motor(Port.D, Direction.CLOCKWISE)
DRIVE_BASE = DriveBase(DRIVE_LEFT, DRIVE_RIGHT, 62.5, 79)
LEFT_ATTACHMENT = Motor(Port.E, Direction.CLOCKWISE)
RIGHT_ATTACHMENT = Motor(Port.A, Direction.CLOCKWISE)
LEFT_COLOR_SENSOR = ColorSensor(Port.B)
RIGHT_COLOR_SENSOR = ColorSensor(Port.F)
SPEED = 950
ACCELERATION = 1300
TURN_SPEED = 200
TURN_ACCELERATION = 400
MANUAL_MOTOR_SPEED = 250
TELEOP_SPEED = 300
TELEOP_ACCEL = 1000
TELEOP_TURN = 200
TELEOP_TURN_ACCEL = 1000
TELEOP_ATTACH_SPEED = 600
watch = StopWatch()


